'use client'

import { useStrings, type StringsOverrides } from './strings'
import * as React from 'react'
import './loading.css'
import './gamestage-primitives.css'

/**
 * Loading: the state a player sees while the game is being fetched, drawn
 * rather than written. GSUI-282, with Gamestage GS-537.
 *
 * Tom, 2026-09-27: the smoothest possible loading, a spinner or a bar rather
 * than text, nicely centred. So this fills its container and centres one
 * mark in it. The words are for screen readers only; a sighted player sees a
 * spinner, or a bar when the host knows how far through it is.
 *
 * It holds its container's size, so the game that replaces it arrives in one
 * step rather than jumping in. Reduced motion turns the spin into a slow pulse.
 * Page-level first paint, before any script runs, is the host's HTML's job
 * (Gamestage's scaffolds draw the same mark there); this is the same state for
 * everything after the scripts have started.
 */
export interface LoadingProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** `spinner` when there is no measure of progress, `bar` when there is. Default `spinner`. */
  variant?: 'spinner' | 'bar'
  /** For `bar`: how far through, 0 to 1. Absent draws a bar that sweeps. */
  value?: number
  /** The words for this instance. */
  strings?: StringsOverrides
}

export function Loading({ variant = 'spinner', value, strings, className, ...rest }: LoadingProps) {
  const copy = useStrings(strings)
  const known = variant === 'bar' && typeof value === 'number' && Number.isFinite(value)
  const fraction = known ? Math.min(1, Math.max(0, value as number)) : undefined
  const percent = fraction === undefined ? undefined : Math.round(fraction * 100)
  return (
    <div
      {...rest}
      className={['gs-loading', className].filter(Boolean).join(' ')}
      data-gs-component="loading"
      data-gs-loading={variant}
      role="status"
      aria-busy="true"
    >
      {variant === 'bar' ? (
        <div
          className="gs-loading__track"
          data-gs-scope="loading"
          data-gs-part="track"
          role="progressbar"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={percent}
          aria-label={percent === undefined ? copy['loading.label'] : copy['loading.progress'](percent)}
          style={fraction === undefined ? undefined : ({ '--gs-loading-fraction': String(fraction) } as React.CSSProperties)}
        >
          <span className="gs-loading__fill" data-gs-scope="loading" data-gs-part="fill" />
        </div>
      ) : (
        <span className="gs-loading__spinner" data-gs-scope="loading" data-gs-part="spinner" aria-hidden="true" />
      )}
      <span className="gs-loading__label" data-gs-scope="loading" data-gs-part="label">
        {percent === undefined ? copy['loading.label'] : copy['loading.progress'](percent)}
      </span>
    </div>
  )
}

/* Loading. Tokens only: no literal colour and no literal size. It fills its
   container and centres one mark, so what replaces it arrives in one step. */

.gs-loading {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  min-height: var(--gs-size-action-large);
}

.gs-loading__spinner {
  width: var(--gs-size-icon-hero);
  height: var(--gs-size-icon-hero);
  border-radius: var(--gs-radius-full);
  border: var(--gs-space-1) solid var(--gs-color-edge);
  border-top-color: var(--gs-color-interactive-solid);
  /* One turn per pulse, at the rays' constant speed curve. */
  animation: gs-loading-spin var(--gs-motion-pulse) var(--gs-motion-ease-rays) infinite;
}

.gs-loading__track {
  position: relative;
  width: min(100%, calc(var(--gs-size-action-large) * 4));
  height: var(--gs-space-2);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-edge);
  overflow: hidden;
}

.gs-loading__fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--gs-loading-fraction, 0.35) * 100%);
  border-radius: inherit;
  background: var(--gs-color-interactive);
  transition: width var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

/* No measure of progress: the fill sweeps. */
.gs-loading__track:not([style]) .gs-loading__fill {
  animation: gs-loading-sweep var(--gs-motion-pulse) var(--gs-motion-ease-pulse) infinite;
}

/* The words are for screen readers; the mark is what a sighted player reads. */
.gs-loading__label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@keyframes gs-loading-spin {
  to { transform: rotate(360deg); }
}

@keyframes gs-loading-sweep {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(290%); }
}

@keyframes gs-loading-pulse {
  50% { opacity: 0.45; }
}

@media (prefers-reduced-motion: reduce) {
  .gs-loading__spinner,
  .gs-loading__track:not([style]) .gs-loading__fill {
    animation: gs-loading-pulse var(--gs-motion-glow) var(--gs-motion-ease-glow) infinite;
  }
}
